16	#include "onnx_common.h"
17	
18	namespace domi {
19	using NodeProto = ge::onnx::NodeProto;
20	static const int REQUIRED_ATTRS_NUM = 6;
21	static Status ParseParamsMultiHeadAttention(const Message *op_src, ge::Operator &op_dest)
22	{
23	    const NodeProto *node = dynamic_cast<const NodeProto *>(op_src);
24	    if (node == nullptr) {
25	        OP_LOGE("MultiHeadAttention", "Dynamic cast op_src to NodeProto failed.");
26	        return FAILED;
27	    }
28	    int attn_head_num = 0;
29	    int attn_dim_per_head = 0;
