37	            attn_head_num = attr.i();
38	            ++attr_num;
39	        } else if (attr.name() == "attn_dim_per_head" && attr.type() == ge::onnx::AttributeProto::INT) {
40	            attn_dim_per_head = attr.i();
41	            ++attr_num;
42	        } else if (attr.name() == "src_len" && attr.type() == ge::onnx::AttributeProto::INT) {
43	            src_len = attr.i();
44	            ++attr_num;
45	        } else if (attr.name() == "tgt_len" && attr.type() == ge::onnx::AttributeProto::INT) {
46	            tgt_len = attr.i();
47	            ++attr_num;
48	        } else if (attr.name() == "dropout_prob" && attr.type() == ge::onnx::AttributeProto::FLOAT) {
49	            dropout_prob = attr.f();
50	            ++attr_num;
51	        } else if (attr.name() == "softmax_use_float" && attr.type() == ge::onnx::AttributeProto::INT) {
52	            softmax_use_float = attr.i();
