55	    }
56	
57	    if (attr_num != REQUIRED_ATTRS_NUM) {
58	        OP_LOGE(GetOpName(op_dest).c_str(), "Node must have attrs attn_head_num/attn_dim_per_head/"
59	                                            "src_len/tgt_len/dropout_prob/softmax_use_float");
60	        return FAILED;
61	    }
62	    op_dest.SetAttr("attn_head_num", attn_head_num);
63	    op_dest.SetAttr("attn_dim_per_head", attn_dim_per_head);
