11	/*!
12	 * \file npu_flash_attention_score_onnx_plugin.cpp
13	 * \brief
14	 */
15	#include "onnx_common.h"
16	#include "attention/flash_attention_score/op_graph/flash_attention_score_proto.h"
17	#include "op_common/log/log.h"
18	
19	namespace domi {
20	using NodeProto = ge::onnx::NodeProto;
21	constexpr int REQUIRED_ATTR = 2;
22	constexpr int ACL_UINT8 = 4;
23	constexpr int ONE = 1;
24	constexpr int ALIGN_NUM = 128;
25	constexpr int ONE_BYTE_BITS = 8;
26	constexpr int EXTRA_LENGTH = 32;
27	constexpr int OUTPUT_INDEX = 3;
28	
29	namespace{
30	static void UpdateFlashAttentionByNode(ge::Operator& op_dest, const NodeProto* node) {
31	  int input_size = node->input_size();
32	  int output_size = node->output_size();
33	  op_dest.DynamicInputRegister("x", input_size);
34	  op_dest.DynamicOutputRegister("y", output_size);
35	  op_dest.SetAttr("name", node->name());
36	  op_dest.SetAttr("original_type", "npu::1::NPUFlashAttention");
37	}
38	
39	static Status GetAttrFromPre4(
40	  const ge::Operator& op, int& head_num, string& input_layout, float& scale, float& keep_prob) {
41	  if (op.GetAttr("head_num", head_num) != SUCCESS) {
42	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "head_num",
43	        "get head_num from op failed");
44	    return FAILED;
45	  }
46	  if (op.GetAttr("input_layout", input_layout) != SUCCESS) {
47	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "input_layout",
48	        "get input_layout from op failed");
49	    return FAILED;
50	  }
51	  if (op.GetAttr("scale", scale) != SUCCESS) {
52	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "scale",
53	        "get scale from op failed");
54	    return FAILED;
55	  }
56	  if (op.GetAttr("keep_prob", keep_prob) != SUCCESS) {
57	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "keep_prob",
58	        "get keep_prob from op failed");
59	    return FAILED;
60	  }
61	  return SUCCESS;
62	}
63	
64	static Status GetAttrFromLast4(
65	  const ge::Operator& op, int& pre_tockens, int& next_tockens, int& inner_precise, int& sparse_mode) {
66	  if (op.GetAttr("pre_tockens", pre_tockens) != SUCCESS) {
67	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "pre_tockens",
68	        "get pre_tockens from op failed");
69	    return FAILED;
70	  }
71	  if (op.GetAttr("next_tockens", next_tockens) != SUCCESS) {
72	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "next_tockens",
73	        "get next_tockens from op failed");
74	    return FAILED;
75	  }
76	  if (op.GetAttr("inner_precise", inner_precise) != SUCCESS) {
77	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "inner_precise",
78	        "get inner_precise from op failed");
79	    return FAILED;
80	  }
81	  if (op.GetAttr("sparse_mode", sparse_mode) != SUCCESS) {
82	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "sparse_mode",
83	        "get sparse_mode from op failed");
84	    return FAILED;
85	  }
86	  return SUCCESS;
87	}
88	
89	static Status GetFinalDimsByOperator(
90	  const ge::Operator& op, const std::string& input_layout, int head_num, vector<int64_t>& final_dims) {
91	  std::vector<int64_t> dims = op.GetInputDesc(0).GetShape().GetDims();
92	  int64_t numels = 0;
93	  if (input_layout == "BSH") {
94	    numels = dims[0] * dims[1] * dims[1] * head_num;
95	  } else if (input_layout == "SBH") {
96	    numels = dims[1] * dims[0] * dims[0] * head_num;
97	  } else {
98	    OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(GetOpName(op).c_str(), "input_layout",
99	        input_layout, "The value of input_layout must be BSH or SBH");
100	    return FAILED;
101	  }
102	  int64_t length = (numels + ALIGN_NUM - 1) / ALIGN_NUM * ALIGN_NUM / ONE_BYTE_BITS;
103	  length += EXTRA_LENGTH;
104	  final_dims = {length};
105	  return SUCCESS;
106	}
107	
108	static Status GetOriNameFromOperator(const ge::Operator& op, std::string& ori_name) {
109	  if (op.GetAttr("name", ori_name) != SUCCESS) {
110	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op).c_str(), "name",
111	        "get name from op failed");
112	    return FAILED;
113	  }
114	  return SUCCESS;
115	}
116	}
117	
118	static Status ParseParamsFlashAttention(const Message* op_src, ge::Operator& op_dest) {
119	  const NodeProto* node = dynamic_cast<const NodeProto*>(op_src);
120	  if (node == nullptr) {
121	    OP_LOGE("FlashAttention", "Dynamic cast op_src to NodeProto failed.");
122	    return FAILED;
123	  }
124	
125	  int head_num = 0;
126	  std::string input_layout = "";
127	  float scale = 1.0f;
128	  float keep_prob = 1.0f;
129	  int pre_tockens = 0;
130	  int next_tockens = 0;
131	  int required_attr_num = 0;
132	  int inner_precise = 1;
133	  int sparse_mode = 0;
134	  for (const auto& attr : node->attribute()) {
135	    if (attr.name() == "head_num" && attr.type() == ge::onnx::AttributeProto::INT) {
136	      head_num = attr.i();
137	      ++required_attr_num;
138	    } else if (attr.name() == "input_layout" && attr.type() == ge::onnx::AttributeProto::STRING) {
139	      input_layout = attr.s();
140	      ++required_attr_num;
141	    } else if (attr.name() == "scale" && attr.type() == ge::onnx::AttributeProto::FLOAT) {
142	      scale = attr.f();
143	    } else if (attr.name() == "keep_prob" && attr.type() == ge::onnx::AttributeProto::FLOAT) {
144	      keep_prob = attr.f();
145	    } else if (attr.name() == "pre_tockens" && attr.type() == ge::onnx::AttributeProto::INT) {
146	      pre_tockens = attr.i();
147	    } else if (attr.name() == "next_tockens" && attr.type() == ge::onnx::AttributeProto::INT) {
148	      next_tockens = attr.i();
149	    } else if (attr.name() == "inner_precise" && attr.type() == ge::onnx::AttributeProto::INT) {
150	      inner_precise = attr.i();
151	    } else if (attr.name() == "sparse_mode" && attr.type() == ge::onnx::AttributeProto::INT) {
152	      sparse_mode = attr.i();
153	    }
154	  }
155	
156	  if (required_attr_num != REQUIRED_ATTR) {
157	    OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(GetOpName(op_dest).c_str(),
158	        "required_attr_num", "attr num two is required.");
159	    return FAILED;
160	  }
161	
162	  UpdateFlashAttentionByNode(op_dest, node);
163	
164	  op_dest.SetAttr("head_num", head_num);
165	  op_dest.SetAttr("input_layout", input_layout);
166	  op_dest.SetAttr("scale", scale);
167	  op_dest.SetAttr("keep_prob", keep_prob);
168	  op_dest.SetAttr("pre_tockens", pre_tockens);
169	  op_dest.SetAttr("next_tockens", next_tockens);
170	  op_dest.SetAttr("inner_precise", inner_precise);
171	  op_dest.SetAttr("sparse_mode", sparse_mode);
172	  return SUCCESS;
173	}
174	
175	static Status ParseOpToGraphNpuFlashAttentionScore(const ge::Operator& op, ge::Graph& graph) {
176	  std::string ori_name;
177	  if (GetOriNameFromOperator(op, ori_name)) {
178	    return FAILED;
179	  }
180	
181	  auto data0 = ge::op::Data((ori_name + "_data0").c_str()).set_attr_index(0);
182	  auto data1 = ge::op::Data((ori_name + "_data1").c_str()).set_attr_index(1);
183	  auto data2 = ge::op::Data((ori_name + "_data2").c_str()).set_attr_index(2);
184	  auto data3 = ge::op::Data((ori_name + "_data3").c_str()).set_attr_index(3);
185	  auto data4 = ge::op::Data((ori_name + "_data4").c_str()).set_attr_index(4);
186	  auto data5 = ge::op::Data((ori_name + "_data5").c_str()).set_attr_index(5);
187	  auto data6 = ge::op::Data((ori_name + "_data6").c_str()).set_attr_index(6);
188	  auto data7 = ge::op::Data((ori_name + "_data7").c_str()).set_attr_index(7);
189	  auto data8 = ge::op::Data((ori_name + "_data8").c_str()).set_attr_index(8);
190	
191	  int head_num = 0;
192	  string input_layout = "BSH";
193	  float scale = 1.0f;
194	  float keep_prob = 1.0f;
195	  int pre_tockens = 0;
196	  int next_tockens = 0;
197	  int inner_precise = 1;
198	  int sparse_mode = 0;
199	  if ((GetAttrFromPre4(op, head_num, input_layout, scale, keep_prob) != SUCCESS) ||
200	      (GetAttrFromLast4(op, pre_tockens, next_tockens, inner_precise, sparse_mode) != SUCCESS)) {
201	    return FAILED;
202	  }
203	  // create const input tensor "drop_mask" which is filled with the scalar value 1 for inferencing
204	  // deop_mask.size = [B, N, S, S]
205	  ge::Tensor saclar_one = CreateScalar(ONE, ge::DT_UINT8);
206	  auto const_one = ge::op::Const((ori_name + "_Const_one").c_str()).set_attr_value(saclar_one);
207	  vector<int64_t> final_dims;
208	  if (GetFinalDimsByOperator(op, input_layout, head_num, final_dims) != SUCCESS) {
209	    return FAILED;
210	  }
211	
212	  auto tensor_dims = Vec2Tensor(final_dims, {1}, ge::DT_INT64);
213	  auto const_dims = ge::op::Const((ori_name + "_Const_dims").c_str()).set_attr_value(tensor_dims);
214	  auto drop_mask = ge::op::Fill((ori_name + "_Fill_ones").c_str()).set_input_dims(const_dims).set_input_value(const_one);
215	  auto cast_drop_mask = ge::op::Cast((ori_name + "_Cast_drop_mask").c_str()).set_input_x(drop_mask)
216	                                                                            .set_attr_dst_type(ACL_UINT8);
217	
218	  auto AttentionScore = ge::op::FlashAttentionScore((ori_name + "_FlashAttentionScore").c_str())
219	                            .set_input_query(data0).set_input_key(data1).set_input_value(data2)
220	                            .set_input_real_shift(data3).set_input_drop_mask(cast_drop_mask)
221	                            .set_input_padding_mask(data4).set_input_atten_mask(data5).set_input_prefix(data6)
222	                            .set_input_actual_seq_qlen(data7).set_input_actual_seq_kvlen(data8)
223	                            .set_attr_scale_value(scale).set_attr_keep_prob(keep_prob).set_attr_pre_tockens(pre_tockens)
224	                            .set_attr_next_tockens(next_tockens).set_attr_head_num(head_num)
225	                            .set_attr_inner_precise(inner_precise).set_attr_sparse_mode(sparse_mode);
226	  std::vector<ge::Operator> inputs{data0, data1, data2, data3, data4, data5, data6, data7, data8};
227	  std::vector<std::pair<ge::Operator, std::vector<size_t>>> outputs;
228	  outputs.emplace_back(AttentionScore, std::vector<std::size_t>{OUTPUT_INDEX});
229	  graph.SetInputs(inputs).SetOutputs(outputs);
230	  return SUCCESS;
231	}
232	
233	// register npu_flash_attention_score op info to GE
234	REGISTER_CUSTOM_OP("PartitionedCall")
235	  .FrameworkType(ONNX)
236	  .OriginOpType({ge::AscendString("npu::1::NPUFlashAttention"), 
237	                 ge::AscendString("ai.onnx::11::NPUFlashAttention"),
238	                 ge::AscendString("ai.onnx::12::NPUFlashAttention"),
239	                 ge::AscendString("ai.onnx::13::NPUFlashAttention"),
240	                 ge::AscendString("ai.onnx::14::NPUFlashAttention"),
241	                 ge::AscendString("ai.onnx::15::NPUFlashAttention"),
242	                 ge::AscendString("ai.onnx::16::NPUFlashAttention"),
243	                 ge::AscendString("ai.onnx::17::NPUFlashAttention"),
244	                 ge::AscendString("ai.onnx::18::NPUFlashAttention")})
245	  .ParseParamsFn(ParseParamsFlashAttention)
246	  .ParseOpToGraphFn(ParseOpToGraphNpuFlashAttentionScore)
247	  .ImplyType(ImplyType::TVM);
248	}  // namespace domi
